program2.name("gitnexus").description("GitNexus local CLI and MCP server").version(pkg2.version);
program2.command("setup").description("One-time setup: configure MCP for Cursor, Claude Code, OpenCode, Codex").action(createLazyAction(() => Promise.resolve().then(() => (init_setup(), exports_setup)), "setupCommand"));
program2.command("analyze [path]").description("Index a repository (full analysis)").option("-f, --force", "Force full re-index even if up to date").option("--embeddings [limit]", "Enable embedding generation for semantic search (off by default). " + "Optional [limit] overrides the 50,000-node safety cap; pass 0 to disable the cap entirely.").option("--drop-embeddings", "Drop existing embeddings on rebuild. By default, an `analyze` without `--embeddings` " + "preserves any embeddings already present in the index.").option("--skills", "Generate repo-specific skill files from detected communities").option("--skip-agents-md", "Skip updating the gitnexus section in AGENTS.md and CLAUDE.md").option("--no-stats", "Omit volatile file/symbol counts from AGENTS.md and CLAUDE.md").option("--skip-git", "Treat the provided path/cwd as the index root and skip parent git-root discovery").option("--name <alias>", "Register this repo under a custom name in ~/.gitnexus/registry.json " + "(disambiguates repos whose paths share a basename, e.g. two different .../app folders)").option("--allow-duplicate-name", "Register this repo even if another path already uses the same --name alias. " + "Leaves `-r <name>` ambiguous for the two paths; use -r <path> to disambiguate.").option("-v, --verbose", "Enable verbose ingestion warnings (default: false)").option("--max-file-size <kb>", "Skip files larger than this (KB). Default: 512. Hard cap: 32768 (tree-sitter limit).").option("--worker-timeout <seconds>", "Worker sub-batch idle timeout before retry/fallback. Default: 30.").option("--embedding-threads <n>", "Limit local ONNX embedding CPU threads").option("--embedding-batch-size <n>", "Number of nodes per embedding batch").option("--embedding-sub-batch-size <n>", "Number of chunks per embedding model call").option("--embedding-device <device>", "Embedding device: auto, cpu, dml, cuda, or wasm").addHelpText("after", `
Environment variables:
` + `  GITNEXUS_NO_GITIGNORE=1   Skip .gitignore parsing (still reads .gitnexusignore)
` + `  GITNEXUS_MAX_FILE_SIZE=N  Override large-file skip threshold (KB). Default 512, max 32768.
` + `  GITNEXUS_WORKER_SUB_BATCH_TIMEOUT_MS=N  Worker idle timeout in milliseconds. Default 30000.
` + `  GITNEXUS_WORKER_SUB_BATCH_MAX_BYTES=N  Worker job byte budget. Default 8388608.
` + `  GITNEXUS_EMBEDDING_THREADS=N  Limit local ONNX CPU threads for --embeddings.
` + `  GITNEXUS_SEMANTIC_EXACT_SCAN_LIMIT=N  Max embedding chunks for exact-scan fallback. Default 10000.
` + "\nTip: `.gitnexusignore` supports `.gitignore`-style negation. Add e.g.\n" + "     `!__tests__/` to index a directory that is auto-filtered by default (#771).").action(createLazyAction(() => Promise.resolve().then(() => (init_analyze(), exports_analyze)), "analyzeCommand"));
program2.command("index [path...]").description("Register an existing .gitnexus/ folder into the global registry (no re-analysis needed)").option("-f, --force", "Register even if meta.json is missing (stats will be empty)").option("--allow-non-git", "Allow registering folders that are not Git repositories").action(createLazyAction(() => Promise.resolve().then(() => (init_index_repo(), exports_index_repo)), "indexCommand"));
program2.command("serve").description("Start local HTTP server for web UI connection").option("-p, --port <port>", "Port number", "4747").option("--host <host>", "Bind address (default: 127.0.0.1, use 0.0.0.0 for remote access)").action(createLazyAction(() => Promise.resolve().then(() => (init_serve(), exports_serve)), "serveCommand"));
program2.command("mcp").description("Start MCP server (stdio) — serves all indexed repos").action(createLazyAction(() => Promise.resolve().then(() => (init_mcp(), exports_mcp)), "mcpCommand"));
program2.command("list").description("List all indexed repositories").action(createLazyAction(() => Promise.resolve().then(() => (init_list(), exports_list)), "listCommand"));
program2.command("status").description("Show index status for current repo").action(createLazyAction(() => Promise.resolve().then(() => (init_status(), exports_status)), "statusCommand"));
program2.command("doctor").description("Show runtime platform capabilities and embedding configuration").action(createLazyAction(() => Promise.resolve().then(() => (init_doctor(), exports_doctor)), "doctorCommand"));
program2.command("clean").description("Delete GitNexus index for current repo").option("-f, --force", "Skip confirmation prompt").option("--all", "Clean all indexed repos").action(createLazyAction(() => Promise.resolve().then(() => (init_clean(), exports_clean)), "cleanCommand"));
program2.command("remove <target>").description("Delete the GitNexus index for a registered repo (by alias, name, or absolute path). " + "Unlike `clean`, does not require being inside the repo. Idempotent on unknown targets.").option("-f, --force", "Skip confirmation prompt").action(createLazyAction(() => Promise.resolve().then(() => (init_remove(), exports_remove)), "removeCommand"));
program2.command("wiki [path]").description("Generate repository wiki from knowledge graph").option("-f, --force", "Force full regeneration even if up to date").option("--provider <provider>", "LLM provider: openai or cursor (default: openai)").option("--model <model>", "LLM model or Azure deployment name (default: minimax/minimax-m2.5)").option("--base-url <url>", "LLM API base URL. Azure v1: https://{resource}.openai.azure.com/openai/v1").option("--api-key <key>", "LLM API key or Azure api-key (saved to ~/.gitnexus/config.json)").option("--api-version <version>", "Azure api-version query param, e.g. 2024-10-21 (legacy Azure API only)").option("--reasoning-model", "Mark deployment as reasoning model (o1/o3/o4-mini) — strips temperature, uses max_completion_tokens").option("--no-reasoning-model", "Disable reasoning model mode (overrides saved config)").option("--concurrency <n>", "Parallel LLM calls (default: 3)", "3").option("--gist", "Publish wiki as a public GitHub Gist after generation").option("-v, --verbose", "Enable verbose output (show LLM commands and responses)").option("--review", "Stop after grouping to review module structure before generating pages").action(createLazyAction(() => Promise.resolve().then(() => (init_wiki(), exports_wiki)), "wikiCommand"));
program2.command("augment <pattern>").description("Augment a search pattern with knowledge graph context (used by hooks)").action(createLazyAction(() => Promise.resolve().then(() => (init_augment(), exports_augment)), "augmentCommand"));
program2.command("publish [path]").description("Notify the understand-quickly registry that this repo has a fresh GitNexus index. " + "Opt-in: requires UNDERSTAND_QUICKLY_TOKEN (fine-grained PAT with " + "`Repository dispatches: write` on looptech-ai/understand-quickly). " + "No-op without the token. See https://github.com/looptech-ai/understand-quickly.").option("--id <owner/repo>", "Override the registry id (defaults to the origin remote)").option("--skip-git", "Treat cwd as the repo root and skip parent git-root discovery").action(createLazyAction(() => Promise.resolve().then(() => (init_publish(), exports_publish)), "publishCommand"));
program2.command("query <search_query>").description("Search the knowledge graph for execution flows related to a concept").option("-r, --repo <name>", "Target repository (omit if only one indexed)").option("-c, --context <text>", "Task context to improve ranking").option("-g, --goal <text>", "What you want to find").option("-l, --limit <n>", "Max processes to return (default: 5)").option("--content", "Include full symbol source code").action(createLazyAction(() => Promise.resolve().then(() => (init_tool(), exports_tool)), "queryCommand"));
program2.command("context [name]").description("360-degree view of a code symbol: callers, callees, processes").option("-r, --repo <name>", "Target repository").option("-u, --uid <uid>", "Direct symbol UID (zero-ambiguity lookup)").option("-f, --file <path>", "File path to disambiguate common names").option("--content", "Include full symbol source code").action(createLazyAction(() => Promise.resolve().then(() => (init_tool(), exports_tool)), "contextCommand"));
program2.command("impact <target>").description("Blast radius analysis: what breaks if you change a symbol").option("-d, --direction <dir>", "upstream (dependants) or downstream (dependencies)", "upstream").option("-r, --repo <name>", "Target repository").option("--depth <n>", "Max relationship depth (default: 3)").option("--include-tests", "Include test files in results").action(createLazyAction(() => Promise.resolve().then(() => (init_tool(), exports_tool)), "impactCommand"));
program2.command("cypher <query>").description("Execute raw Cypher query against the knowledge graph").option("-r, --repo <name>", "Target repository").action(createLazyAction(() => Promise.resolve().then(() => (init_tool(), exports_tool)), "cypherCommand"));
program2.command("detect-changes").alias("detect_changes").description("Map git diff hunks to indexed symbols and affected execution flows").option("-s, --scope <scope>", "What to analyze: unstaged, staged, all, or compare", "unstaged").option("-b, --base-ref <ref>", "Branch/commit for compare scope (e.g. main)").option("-r, --repo <name>", "Target repository").action(createLazyAction(() => Promise.resolve().then(() => (init_tool(), exports_tool)), "detectChangesCommand"));
program2.command("eval-server").description("Start lightweight HTTP server for fast tool calls during evaluation").option("-p, --port <port>", "Port number", "4848").option("--idle-timeout <seconds>", "Auto-shutdown after N seconds idle (0 = disabled)", "0").action(createLazyAction(() => Promise.resolve().then(() => (init_eval_server(), exports_eval_server)), "evalServerCommand"));
registerGroupCommands(program2);
program2.parse(process.argv);
